size_t numThreads = std::thread::hardware_concurrency();
std::thread threads[numThreads];
size_t blockSize = (end - start) / numThreads;
for (size_t i = 0; i < numThreads; i++) {
    size_t startIdx = start + i * blockSize;
    size_t endIdx = (i == numThreads - 1) ? end : start + (i + 1) * blockSize;
    threads[i] = std::thread([=] {
        for (size_t j = startIdx; j < endIdx; j++) {
            glm::ivec3 cell = getCell(&particles[j], h);
            uint32_t hash = getHash(cell);
            particles[j].hash = hash;
        }
    });
}
for (auto& thread : threads) {
    thread.join();
}

